"""Pure definition cases. Envelopes/Git are supplied, not generated by Rust."""
import copy,json
def vectors():
    cases=[];base=dict(schema_version=1,id='work',revision=2,title='old',objective='old objective',scope='old scope',criteria=['A','B'],tasks=[])
    requests={
        'work.create':dict(schema_version=1,title='Created',objective='Objective',scope='Scope',criteria=['Evidence']),
        'work.update':dict(schema_version=1,title='Updated'),
        'task.add':dict(schema_version=1,id='task',title='Task',deliverable='Proof',criteria=['Evidence']),
        'ooda':dict(schema_version=1,observation='Observe',orientation='Orient',decision='Decide',owner='Owner',next='Next'),
    }
    def frame(name,kind,w=None,r=None,control=False,classification='parity'):
        return dict(Name=name,Kind=kind,Body=json.dumps(base if w is None else w,ensure_ascii=False,separators=(',',':')).encode().hex(),Request=json.dumps(requests[kind]if r is None else r,ensure_ascii=False,separators=(',',':')).encode().hex(),Git=dict(head='fixture-head',branch='fixture-branch',changes='?? fixture'),control=control,classification=classification)
    def pair(name,kind,r=None,w=None,classification='parity'):
        cases.append(frame(name+'-control',kind,control=True));cases.append(frame(name,kind,w,r,classification=classification))
    for kind,r in requests.items():
        for schema in [0,1,2,-1]:pair('schema-'+kind+'-'+str(schema),kind,dict(r,schema_version=schema))
        cases.append(frame('baseline-'+kind,kind,control=True))
    for kind,fields in [('work.create',['title','objective','scope']),('task.add',['id','title','deliverable']),('ooda',['observation','orientation','decision','owner','next'])]:
        for field in fields:
            for value in ['', ' ','\u0085\u3000','é <&>\u2028','\ufeff']:
                pair(kind+'-'+field+'-'+str(len(cases)),kind,dict(requests[kind],**{field:value}))
    for kind in ['work.create','task.add']:
        for criteria in [None,[],[''],[' '],['one','two']]:pair(kind+'-criteria-'+str(len(cases)),kind,dict(requests[kind],criteria=criteria))
    for field,value in [('id','task'),('status','todo'),('depends',[]),('depends',None),('deliverable','proof'),('max_attempts',-1),('max_tool_calls',1),('criteria',[]),('criteria',None),('criteria',[' ']),('criteria',['changed']),('title',' '),('objective','\u0085'),('scope','\u3000'),('owner','ignored'),('next','ignored')]:
        pair('update-field-'+field+'-'+str(len(cases)),'work.update',dict(requests['work.update'],**{field:value}))
    pair('update-no-fields','work.update',dict(schema_version=1))
    for status in ['todo','blocked','running','accepted','submitted','waived','abandoned','']:
        w=copy.deepcopy(base);w['tasks']=[dict(id='existing',status=status,attempts=[dict(id='old')],gate={},automatic_validation={},manual_override={},revalidation={},independent_review=dict(state='passed'))];pair('update-status-'+status,'work.update',w=w)
    for prereq in [None,{},dict(**{'req-1':[]}),dict(**{'req-1':['req-2']}),dict(**{'req-1':['missing']}),dict(**{'req-1':['req-1']})]:
        for kind in ['work.create','work.update']:
            r=dict(requests[kind],requirement_prerequisites=prereq)
            if kind=='work.create':r['criteria']=['A','B']
            classification='atomicity'if prereq and (prereq.get('req-1')in [['missing'],['req-1']])else 'parity'
            pair(kind+'-prerequisite-'+str(len(cases)),kind,r=r,classification=classification)
    for tasks in [[],[dict(id='prior',status='todo')]]:
        for oldmap in [None,{},dict(**{'req-1':['req-2']})]:
            for newmap in [None,{}]:
                w=copy.deepcopy(base);w['tasks']=tasks;w['requirement_prerequisites']=oldmap;r=dict(requests['work.update'],requirement_prerequisites=newmap);pair('prerequisite-task-guard-'+str(len(cases)),'work.update',r,w)
    for depends in [None,[],['prior'],['prior','prior'],['missing'],['task']]:
        w=copy.deepcopy(base);w['tasks']=[dict(id='prior',status='todo')];pair('task-dependency-'+str(len(cases)),'task.add',dict(requests['task.add'],depends=depends),w)
    w=copy.deepcopy(base);w['tasks']=[dict(id='task',status='todo')];pair('duplicate-task','task.add',w=w)
    for result in ['', ' ', 'Outcome']:
        pair('ooda-result-'+str(len(cases)),'ooda',dict(requests['ooda'],result=result))
    for name in ['unknown','work.CREATE','']:
        cases.append(frame('unknown-'+name,'work.update',r=dict(schema_version=1)));cases[-1]['Kind']=name
    assert len(cases)==len({v['Name']for v in cases});return cases
